    "Authority": {"Explanation": "The email references recognized institutions (InfoWorld) and mentions Verdiem, suggesting some level of authority in the field of IT resources and green practices."},
    "Commitment/Consistency": {"Explanation": "The email does not reference prior behavior or choices to push further action, so this principle is not present."},
    "Liking": {"Explanation": "The email does not use personalization or flattery to build trust or rapport with the recipient, so this principle is not present."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsements, so this principle is not present."}
}

